<?php use App\Core\View; use App\Core\Env; $baseUrl=rtrim((string)Env::get('APP_URL',''),'/'); $fullName=$driver['first_name'].' '.$driver['last_name']; $days=(int)floor((strtotime($driver['license_expires_at'])-time())/86400); ?>
<div class="client-detail-heading"><a href="<?= $baseUrl ?>/drivers" class="back-link"><i data-lucide="arrow-left"></i> Retour aux chauffeurs</a><div class="detail-main"><div class="driver-detail-photo"><?php if($driver['has_photo']): ?><img src="<?= $baseUrl.'/drivers/'.(int)$driver['id'].'/photo' ?>" alt="<?= htmlspecialchars($fullName,ENT_QUOTES,'UTF-8') ?>"><?php else: ?><span><?= htmlspecialchars(mb_strtoupper(mb_substr($driver['first_name'],0,1).mb_substr($driver['last_name'],0,1)),ENT_QUOTES,'UTF-8') ?></span><?php endif; ?></div><div><div class="detail-title-line"><h1><?= htmlspecialchars($fullName,ENT_QUOTES,'UTF-8') ?></h1><?= View::partial('components/status-badge',['status'=>$driver['status']]) ?><?= !$driver['is_active']?'<span class="status-badge danger"><i></i>Désactivé</span>':'' ?></div><p><?= htmlspecialchars($driver['code'],ENT_QUOTES,'UTF-8') ?> · Permis <?= htmlspecialchars($driver['license_category'].' '.$driver['license_number'],ENT_QUOTES,'UTF-8') ?></p></div><div class="detail-actions"><?php if($canManage&&$driver['is_active']): ?><button class="button button-secondary" data-deactivate-driver="<?= (int)$driver['id'] ?>"><i data-lucide="user-x"></i> Désactiver</button><button class="button button-primary" data-modal-open="editDriverModal"><i data-lucide="pencil"></i> Modifier</button><?php endif; ?></div></div></div>
<section class="driver-overview-grid"><article class="panel driver-info-card"><div class="detail-card-head"><h2>Coordonnées</h2><i data-lucide="contact"></i></div><dl><div><dt>Téléphone</dt><dd><?= htmlspecialchars($driver['phone'],ENT_QUOTES,'UTF-8') ?></dd></div><div><dt>E-mail</dt><dd><?= htmlspecialchars($driver['email']?:'Non renseigné',ENT_QUOTES,'UTF-8') ?></dd></div><div><dt>Ville</dt><dd><?= htmlspecialchars($driver['city']?:'Non renseignée',ENT_QUOTES,'UTF-8') ?></dd></div><div><dt>Contact d’urgence</dt><dd><?= htmlspecialchars(trim(($driver['emergency_contact_name']??'').' '.($driver['emergency_contact_phone']??''))?:'Non renseigné',ENT_QUOTES,'UTF-8') ?></dd></div></dl></article><article class="panel license-card <?= $days<30?'license-warning':'' ?>"><div class="detail-card-head"><h2>Permis de conduire</h2><i data-lucide="badge-check"></i></div><div class="license-main"><strong><?= htmlspecialchars($driver['license_category'],ENT_QUOTES,'UTF-8') ?></strong><div><span><?= htmlspecialchars($driver['license_number'],ENT_QUOTES,'UTF-8') ?></span><small>Expire le <?= date('d/m/Y',strtotime($driver['license_expires_at'])) ?></small></div></div><div class="expiry-progress"><span style="width:<?= max(4,min(100,$days/365*100)) ?>%"></span></div><p><?= $days<0?'Permis expiré':($days<30?'Expiration dans '.$days.' jour(s)':'Permis valide · '.$days.' jours restants') ?></p></article><article class="panel detail-stats driver-stats"><div><strong><?= count($driver['missions']) ?></strong><span>Missions</span></div><div><strong><?= count(array_filter($driver['incidents'],function($i){return $i['status']!=='Résolu';})) ?></strong><span>Incidents ouverts</span></div><div><strong><?= count($driver['history']) ?></strong><span>Événements</span></div></article></section>
<section class="panel client-tabs-panel"><nav class="detail-tabs"><button class="active" data-detail-tab="missions">Historique des missions <span><?= count($driver['missions']) ?></span></button><button data-detail-tab="incidents">Incidents <span><?= count($driver['incidents']) ?></span></button><button data-detail-tab="history">Historique du dossier <span><?= count($driver['history']) ?></span></button></nav><div class="detail-pane active" data-detail-pane="missions"><?php if(!$driver['missions']): ?><div class="driver-empty"><i data-lucide="route"></i><strong>Aucune mission enregistrée</strong><p>Les futures affectations apparaîtront dans cet historique.</p></div><?php else: ?><div class="professional-table-wrap"><table class="professional-table"><thead><tr><th>Référence</th><th>Itinéraire</th><th>Début</th><th>Fin</th><th>Distance</th><th>Statut</th></tr></thead><tbody><?php foreach($driver['missions'] as $mission): ?><tr><td><strong><?= htmlspecialchars($mission['mission_reference'],ENT_QUOTES,'UTF-8') ?></strong></td><td><?= htmlspecialchars($mission['origin'].' → '.$mission['destination'],ENT_QUOTES,'UTF-8') ?></td><td><?= $mission['started_at']?date('d/m/Y H:i',strtotime($mission['started_at'])):'—' ?></td><td><?= $mission['completed_at']?date('d/m/Y H:i',strtotime($mission['completed_at'])):'—' ?></td><td><?= $mission['distance_km']?htmlspecialchars($mission['distance_km'],ENT_QUOTES,'UTF-8').' km':'—' ?></td><td><?= View::partial('components/status-badge',['status'=>$mission['status']]) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div><div class="detail-pane" data-detail-pane="incidents"><?php if(!$driver['incidents']): ?><div class="driver-empty"><i data-lucide="shield-check"></i><strong>Aucun incident</strong><p>Aucun incident n’est associé à ce chauffeur.</p></div><?php else: ?><div class="incident-list"><?php foreach($driver['incidents'] as $incident): ?><article><span class="incident-severity <?= strtolower($incident['severity']) ?>"><i data-lucide="triangle-alert"></i></span><div><h3><?= htmlspecialchars($incident['incident_reference'].' · '.$incident['severity'],ENT_QUOTES,'UTF-8') ?></h3><p><?= htmlspecialchars($incident['description'],ENT_QUOTES,'UTF-8') ?></p><small><?= date('d/m/Y H:i',strtotime($incident['occurred_at'])) ?></small></div><?= View::partial('components/status-badge',['status'=>$incident['status']]) ?></article><?php endforeach; ?></div><?php endif; ?></div><div class="detail-pane" data-detail-pane="history"><ol class="history-timeline"><?php foreach($driver['history'] as $event): ?><li><span><i data-lucide="<?= $event['action']==='created'?'plus':($event['action']==='deactivated'?'user-x':'pencil') ?>"></i></span><div><strong><?= htmlspecialchars($event['description'],ENT_QUOTES,'UTF-8') ?></strong><p><?= htmlspecialchars($event['user_name']?:'Système',ENT_QUOTES,'UTF-8') ?> · <?= date('d/m/Y à H:i',strtotime($event['created_at'])) ?></p></div></li><?php endforeach; ?></ol></div></section>
<?php if($canManage): ?><div class="modal-backdrop driver-modal" id="editDriverModal" hidden aria-hidden="true"><section class="modal-card modal-driver-large"><div class="modal-head"><div><span class="eyebrow">Dossier chauffeur</span><h2>Modifier <?= htmlspecialchars($fullName,ENT_QUOTES,'UTF-8') ?></h2><p>Mettez à jour l’identité, le permis ou la disponibilité.</p></div><button class="icon-button" type="button" data-modal-close><i data-lucide="x"></i></button></div><?= View::partial('drivers/_form',['formId'=>'editDriverForm','driver'=>$driver,'mobileUsers'=>$mobileUsers]) ?></section></div><?php endif; ?>
